"""Explicit BF16 expansion of the original GPT-OSS MXFP4 checkpoint."""
import os


def gpt_oss_bf16_enabled(hf_config, quantization, dtype, *, is_draft=False):
    value = os.environ.get("SGLANG_GPT_OSS_MXFP4_BF16", "0")
    if value not in {"0", "1"}:
        raise ValueError("SGLANG_GPT_OSS_MXFP4_BF16 must be 0 or 1")
    if value == "0":
        return False
    if getattr(hf_config, "model_type", None) != "gpt_oss":
        return False
    from sglang.srt.utils.common import is_gfx942_supported, is_hip

    config = getattr(hf_config, "quantization_config", None)
    if (
        getattr(hf_config, "architectures", None) != ["GptOssForCausalLM"]
        or not isinstance(config, dict)
        or config.get("quant_method") != "mxfp4"
        or quantization not in {None, "mxfp4"}
        or str(dtype) not in {"auto", "bfloat16", "torch.bfloat16"}
        or is_draft
        or not is_hip()
        or not is_gfx942_supported()
    ):
        raise ValueError("GPT-OSS BF16 expansion requires a gfx942 MXFP4 checkpoint, BF16, and no draft or requantization")
    return True
